public class EmailCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("alice@example.com", true, EmailChecker.isPlausibleEmail("alice@example.com"));
        check("bob.smith_99@mail.example-site.org", true, EmailChecker.isPlausibleEmail("bob.smith_99@mail.example-site.org"));
        check("no.at.sign.com", false, EmailChecker.isPlausibleEmail("no.at.sign.com"));
        check("a@b@c.com (two @)", false, EmailChecker.isPlausibleEmail("a@b@c.com"));
        check("user@example (no dot)", false, EmailChecker.isPlausibleEmail("user@example"));
        check("user@site.c (TLD too short)", false, EmailChecker.isPlausibleEmail("user@site.c"));
        check("user@site.c0m (TLD has digit)", false, EmailChecker.isPlausibleEmail("user@site.c0m"));
        check("@example.com (empty local part)", false, EmailChecker.isPlausibleEmail("@example.com"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

