public class EmailChecker {

    public static boolean isPlausibleEmail(String s) {
        return s.matches("[A-Za-z0-9._-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}");
    }
}
